import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { Plus, Tag, Trash2, X, ToggleLeft, ToggleRight } from "lucide-react";

const CATEGORIES = ["Food", "Beverage", "Electronics", "Clothing", "Health", "Household", "Other"];
const TYPE_LABELS = { percent: "% Off Cart", fixed: "$ Fixed Off", bogo: "Buy 1 Get 1", category_percent: "Category %" };
const TYPE_COLORS = { percent: "text-blue-400", fixed: "text-green-400", bogo: "text-pink-400", category_percent: "text-amber-400" };
const EMPTY = { code: "", type: "percent", value: "", category: "", min_purchase: "", max_uses: "", expires: "", description: "", active: true };

export default function CouponPanel() {
  const [coupons, setCoupons] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modal, setModal] = useState(false);
  const [form, setForm] = useState(EMPTY);
  const [saving, setSaving] = useState(false);

  const load = () => {
    setLoading(true);
    base44.entities.Coupon.list("-created_date", 200).then(c => { setCoupons(c); setLoading(false); });
  };

  useEffect(() => { load(); }, []);

  const save = async () => {
    setSaving(true);
    await base44.entities.Coupon.create({
      ...form,
      code: form.code.toUpperCase(),
      value: parseFloat(form.value) || 0,
      min_purchase: parseFloat(form.min_purchase) || 0,
      max_uses: form.max_uses ? parseInt(form.max_uses) : null,
      uses: 0
    });
    setSaving(false);
    setModal(false);
    setForm(EMPTY);
    load();
  };

  const toggle = async (coupon) => {
    await base44.entities.Coupon.update(coupon.id, { active: !coupon.active });
    load();
  };

  const deleteCoupon = async (id) => {
    await base44.entities.Coupon.delete(id);
    load();
  };

  if (loading) return <div className="text-green-400 font-mono animate-pulse p-6">Loading coupons...</div>;

  const activeCoupons = coupons.filter(c => c.active).length;

  return (
    <div className="h-full flex flex-col">
      <div className="p-4 border-b border-gray-800 flex items-center justify-between">
        <div className="text-xs font-mono text-gray-500">
          {activeCoupons} active of {coupons.length} coupons
        </div>
        <button onClick={() => { setForm(EMPTY); setModal(true); }}
          className="flex items-center gap-1.5 bg-green-700 hover:bg-green-600 text-white text-xs font-mono px-3 py-2 rounded-lg transition">
          <Plus className="w-3.5 h-3.5" /> Create Coupon
        </button>
      </div>

      <div className="flex-1 overflow-y-auto">
        <table className="w-full text-xs font-mono">
          <thead className="sticky top-0 bg-gray-900 border-b border-gray-800">
            <tr>{["Code", "Type", "Discount", "Min Purchase", "Uses", "Expires", "Status", "Actions"].map(h => (
              <th key={h} className="text-left text-gray-500 px-4 py-2">{h}</th>
            ))}</tr>
          </thead>
          <tbody>
            {coupons.map(c => (
              <tr key={c.id} className={`border-b border-gray-800/60 hover:bg-gray-800/30 ${!c.active ? "opacity-50" : ""}`}>
                <td className="px-4 py-2.5 text-white font-bold tracking-widest">{c.code}</td>
                <td className={`px-4 py-2.5 ${TYPE_COLORS[c.type] || "text-gray-400"}`}>{TYPE_LABELS[c.type] || c.type}</td>
                <td className="px-4 py-2.5 text-white">
                  {c.type === "percent" ? `${c.value}% off`
                    : c.type === "fixed" ? `$${c.value} off`
                    : c.type === "bogo" ? "Cheapest item free"
                    : `${c.value}% off ${c.category}`}
                </td>
                <td className="px-4 py-2.5 text-gray-400">{c.min_purchase ? `$${c.min_purchase}` : "—"}</td>
                <td className="px-4 py-2.5 text-gray-400">{c.uses || 0}{c.max_uses ? `/${c.max_uses}` : ""}</td>
                <td className="px-4 py-2.5 text-gray-500">{c.expires || "Never"}</td>
                <td className="px-4 py-2.5">{c.active ? <span className="text-green-400">Active</span> : <span className="text-gray-500">Inactive</span>}</td>
                <td className="px-4 py-2.5">
                  <div className="flex gap-2">
                    <button onClick={() => toggle(c)} className="text-gray-500 hover:text-blue-400 transition">
                      {c.active ? <ToggleRight className="w-4 h-4" /> : <ToggleLeft className="w-4 h-4" />}
                    </button>
                    <button onClick={() => deleteCoupon(c.id)} className="text-gray-500 hover:text-red-400 transition">
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {coupons.length === 0 && (
              <tr><td colSpan={8} className="text-gray-600 text-center py-12 font-mono">No coupons created yet</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {modal && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 w-full max-w-md max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <div className="text-white font-bold flex items-center gap-2"><Tag className="w-4 h-4 text-blue-400" /> Create Coupon</div>
              <button onClick={() => setModal(false)} className="text-gray-500 hover:text-gray-300"><X className="w-4 h-4" /></button>
            </div>
            <div className="space-y-3">
              <div>
                <label className="text-gray-500 text-xs font-mono block mb-1">Coupon Code *</label>
                <input value={form.code} onChange={e => setForm(p => ({ ...p, code: e.target.value.toUpperCase() }))} placeholder="SAVE20"
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
              </div>
              <div>
                <label className="text-gray-500 text-xs font-mono block mb-1">Discount Type *</label>
                <select value={form.type} onChange={e => setForm(p => ({ ...p, type: e.target.value }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500">
                  <option value="percent">Percentage Off (e.g. 20% off everything)</option>
                  <option value="fixed">Fixed Amount Off (e.g. $5 off total)</option>
                  <option value="bogo">Buy One Get One Free (cheapest item free)</option>
                  <option value="category_percent">Category Discount (% off specific category)</option>
                </select>
              </div>
              {form.type !== "bogo" && (
                <div>
                  <label className="text-gray-500 text-xs font-mono block mb-1">
                    {form.type === "fixed" ? "Discount Amount ($) *" : "Discount Percentage (%) *"}
                  </label>
                  <input type="number" value={form.value} onChange={e => setForm(p => ({ ...p, value: e.target.value }))}
                    placeholder={form.type === "fixed" ? "5.00" : "20"}
                    className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
                </div>
              )}
              {form.type === "category_percent" && (
                <div>
                  <label className="text-gray-500 text-xs font-mono block mb-1">Apply to Category *</label>
                  <select value={form.category} onChange={e => setForm(p => ({ ...p, category: e.target.value }))}
                    className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500">
                    <option value="">Select category…</option>
                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
              )}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-gray-500 text-xs font-mono block mb-1">Min Purchase ($)</label>
                  <input type="number" value={form.min_purchase} onChange={e => setForm(p => ({ ...p, min_purchase: e.target.value }))} placeholder="0"
                    className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
                </div>
                <div>
                  <label className="text-gray-500 text-xs font-mono block mb-1">Max Uses (blank = ∞)</label>
                  <input type="number" value={form.max_uses} onChange={e => setForm(p => ({ ...p, max_uses: e.target.value }))} placeholder="Unlimited"
                    className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
                </div>
              </div>
              <div>
                <label className="text-gray-500 text-xs font-mono block mb-1">Expiry Date (optional)</label>
                <input type="date" value={form.expires} onChange={e => setForm(p => ({ ...p, expires: e.target.value }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
              </div>
              <div>
                <label className="text-gray-500 text-xs font-mono block mb-1">Description</label>
                <input value={form.description} onChange={e => setForm(p => ({ ...p, description: e.target.value }))} placeholder="Summer sale promo…"
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
              </div>
            </div>
            <div className="flex gap-2 mt-5">
              <button onClick={() => setModal(false)} className="flex-1 bg-gray-800 hover:bg-gray-700 border border-gray-700 text-gray-300 py-2 rounded-xl text-sm transition">Cancel</button>
              <button onClick={save} disabled={saving || !form.code || (form.type !== "bogo" && !form.value)}
                className="flex-1 bg-green-700 hover:bg-green-600 disabled:opacity-40 text-white font-bold py-2 rounded-xl text-sm transition">
                {saving ? "Creating…" : "Create Coupon"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

src/components/pos/CustomerPanel.jsx:
import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { Search, Plus, Pencil, Trash2, X, Star, ShoppingBag, Phone, Mail, ChevronDown, ChevronUp } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

const EMPTY = { first_name: "", last_name: "", email: "", phone: "", address: "", notes: "" };

function CustomerForm({ initial, onSave, onCancel }) {
  const [form, setForm] = useState(initial || EMPTY);
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));
  return (
    <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 w-full max-w-md shadow-2xl">
        <div className="flex justify-between items-center mb-4">
          <div className="text-white font-bold font-mono">{initial?.id ? "Edit Customer" : "New Customer"}</div>
          <button onClick={onCancel}><X className="w-4 h-4 text-gray-500" /></button>
        </div>
        <div className="space-y-3">
          <div className="grid grid-cols-2 gap-3">
            <input placeholder="First Name *" value={form.first_name} onChange={e => set("first_name", e.target.value)}
              className="bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-600" />
            <input placeholder="Last Name *" value={form.last_name} onChange={e => set("last_name", e.target.value)}
              className="bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-600" />
          </div>
          <input placeholder="Email" value={form.email} onChange={e => set("email", e.target.value)}
            className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-600" />
          <input placeholder="Phone" value={form.phone} onChange={e => set("phone", e.target.value)}
            className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-600" />
          <input placeholder="Address" value={form.address} onChange={e => set("address", e.target.value)}
            className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-600" />
          <textarea placeholder="Notes" value={form.notes} onChange={e => set("notes", e.target.value)} rows={2}
            className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-600 resize-none" />
        </div>
        <div className="flex gap-2 mt-4">
          <button onClick={onCancel} className="flex-1 bg-gray-800 border border-gray-700 text-gray-300 py-2 rounded-xl text-sm font-mono transition hover:bg-gray-700">Cancel</button>
          <button onClick={() => onSave(form)} disabled={!form.first_name || !form.last_name}
            className="flex-1 bg-green-700 hover:bg-green-600 text-white font-bold py-2 rounded-xl text-sm font-mono transition disabled:opacity-40">Save</button>
        </div>
      </div>
    </div>
  );
}

function CustomerDetail({ customer, transactions, onClose, onEdit, onAdjustPoints }) {
  const [pointsAdj, setPointsAdj] = useState("");
  const txList = transactions.filter(t => t.customer_id === customer.id);
  return (
    <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 w-full max-w-lg shadow-2xl max-h-[90vh] overflow-y-auto">
        <div className="flex justify-between items-center mb-4">
          <div>
            <div className="text-white font-bold text-lg font-mono">{customer.first_name} {customer.last_name}</div>
            <div className="text-gray-500 text-xs font-mono mt-0.5">Customer Profile</div>
          </div>
          <div className="flex gap-2">
            <button onClick={() => onEdit(customer)} className="text-gray-500 hover:text-blue-400 transition"><Pencil className="w-4 h-4" /></button>
            <button onClick={onClose}><X className="w-4 h-4 text-gray-500" /></button>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-3 gap-3 mb-4">
          {[
            { label: "Loyalty Pts", value: customer.loyalty_points || 0, color: "text-amber-400" },
            { label: "Total Spent", value: `$${(customer.total_spent || 0).toFixed(2)}`, color: "text-green-400" },
            { label: "Visits", value: customer.visit_count || 0, color: "text-blue-400" },
          ].map(s => (
            <div key={s.label} className="bg-gray-800 rounded-xl p-3 text-center">
              <div className={`font-bold font-mono text-lg ${s.color}`}>{s.value}</div>
              <div className="text-gray-500 text-xs font-mono">{s.label}</div>
            </div>
          ))}
        </div>

        {/* Contact info */}
        <div className="bg-gray-800 rounded-xl p-3 mb-4 space-y-1.5 text-xs font-mono">
          {customer.email && <div className="flex items-center gap-2 text-gray-400"><Mail className="w-3.5 h-3.5" />{customer.email}</div>}
          {customer.phone && <div className="flex items-center gap-2 text-gray-400"><Phone className="w-3.5 h-3.5" />{customer.phone}</div>}
          {customer.notes && <div className="text-gray-500 italic">{customer.notes}</div>}
        </div>

        {/* Adjust points */}
        <div className="flex gap-2 mb-4">
          <input type="number" placeholder="Adjust points (e.g. +50 or -10)" value={pointsAdj} onChange={e => setPointsAdj(e.target.value)}
            className="flex-1 bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-xs font-mono focus:outline-none focus:border-amber-600" />
          <button onClick={() => { onAdjustPoints(customer, parseInt(pointsAdj)); setPointsAdj(""); }}
            disabled={!pointsAdj}
            className="bg-amber-700 hover:bg-amber-600 text-white text-xs font-mono px-3 py-2 rounded-lg transition disabled:opacity-40">Apply</button>
        </div>

        {/* Purchase history */}
        <div className="text-gray-400 text-xs font-mono font-semibold mb-2">Purchase History ({txList.length})</div>
        {txList.length === 0 ? (
          <div className="text-gray-600 text-xs font-mono text-center py-6">No transactions linked to this customer</div>
        ) : (
          <div className="space-y-2 max-h-48 overflow-y-auto">
            {txList.sort((a,b) => new Date(b.timestamp) - new Date(a.timestamp)).map(t => (
              <div key={t.id} className="bg-gray-800 rounded-lg px-3 py-2 flex justify-between items-center text-xs font-mono">
                <div>
                  <div className="text-white">{t.transaction_id}</div>
                  <div className="text-gray-500">{t.timestamp ? new Date(t.timestamp).toLocaleString() : "—"}</div>
                </div>
                <div className="text-green-400 font-bold">${(t.total || 0).toFixed(2)}</div>
              </div>
            ))}
          </div>
        )}

        <button onClick={onClose} className="w-full mt-4 bg-gray-800 border border-gray-700 text-gray-300 py-2 rounded-xl text-sm font-mono hover:bg-gray-700 transition">Close</button>
      </div>
    </div>
  );
}

export default function CustomerPanel() {
  const [customers, setCustomers] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState(null);
  const [viewing, setViewing] = useState(null);
  const [deleteConfirm, setDeleteConfirm] = useState(null);

  useEffect(() => {
    Promise.all([
      base44.entities.Customer.list("first_name", 500),
      base44.entities.Transaction.list("-timestamp", 500)
    ]).then(([c, t]) => { setCustomers(c); setTransactions(t); setLoading(false); });
  }, []);

  const load = () => base44.entities.Customer.list("first_name", 500).then(setCustomers);

  const filtered = customers.filter(c => {
    const q = search.toLowerCase();
    return !q || `${c.first_name} ${c.last_name}`.toLowerCase().includes(q) || c.email?.toLowerCase().includes(q) || c.phone?.includes(q);
  });

  const handleSave = async (form) => {
    if (editing?.id) await base44.entities.Customer.update(editing.id, form);
    else await base44.entities.Customer.create(form);
    setEditing(null);
    load();
  };

  const handleDelete = async (c) => {
    await base44.entities.Customer.delete(c.id);
    setDeleteConfirm(null);
    load();
  };

  const handleAdjustPoints = async (customer, delta) => {
    const newPts = Math.max(0, (customer.loyalty_points || 0) + delta);
    await base44.entities.Customer.update(customer.id, { loyalty_points: newPts });
    setViewing({ ...customer, loyalty_points: newPts });
    load();
  };

  if (loading) return <div className="text-green-400 font-mono animate-pulse p-6">Loading customers...</div>;

  return (
    <div className="h-full flex flex-col">
      {/* Toolbar */}
      <div className="p-4 border-b border-gray-800 flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-2.5 w-3.5 h-3.5 text-gray-500" />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search customers…"
            className="w-full bg-gray-800 border border-gray-700 rounded-lg pl-8 pr-3 py-2 text-white text-xs font-mono focus:outline-none focus:border-green-600 transition" />
        </div>
        <button onClick={() => setEditing({})}
          className="flex items-center gap-1.5 bg-green-700 hover:bg-green-600 text-white text-xs font-mono px-3 py-2 rounded-lg transition">
          <Plus className="w-3.5 h-3.5" /> Add Customer
        </button>
        <div className="text-gray-600 text-xs font-mono">{filtered.length} customers</div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-y-auto">
        {filtered.length === 0 ? (
          <div className="text-gray-600 font-mono text-sm text-center py-16">No customers found</div>
        ) : (
          <table className="w-full text-xs font-mono">
            <thead className="sticky top-0 bg-gray-900 border-b border-gray-800">
              <tr>
                {["Name", "Email", "Phone", "Loyalty Pts", "Total Spent", "Visits", "Actions"].map(h => (
                  <th key={h} className="text-left text-gray-500 px-4 py-2 font-medium">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map(c => (
                <tr key={c.id} className="border-b border-gray-800/60 hover:bg-gray-800/30 transition cursor-pointer" onClick={() => setViewing(c)}>
                  <td className="px-4 py-2.5 text-white font-semibold">{c.first_name} {c.last_name}</td>
                  <td className="px-4 py-2.5 text-gray-400">{c.email || "—"}</td>
                  <td className="px-4 py-2.5 text-gray-400">{c.phone || "—"}</td>
                  <td className="px-4 py-2.5">
                    <span className="text-amber-400 font-bold flex items-center gap-1"><Star className="w-3 h-3" />{c.loyalty_points || 0}</span>
                  </td>
                  <td className="px-4 py-2.5 text-green-400 font-bold">${(c.total_spent || 0).toFixed(2)}</td>
                  <td className="px-4 py-2.5 text-blue-400">{c.visit_count || 0}</td>
                  <td className="px-4 py-2.5" onClick={e => e.stopPropagation()}>
                    <div className="flex gap-2">
                      <button onClick={() => setEditing(c)} className="text-gray-500 hover:text-blue-400 transition"><Pencil className="w-3.5 h-3.5" /></button>
                      <button onClick={() => setDeleteConfirm(c)} className="text-gray-500 hover:text-red-400 transition"><Trash2 className="w-3.5 h-3.5" /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {editing !== null && <CustomerForm initial={editing} onSave={handleSave} onCancel={() => setEditing(null)} />}

      {viewing && (
        <CustomerDetail
          customer={viewing}
          transactions={transactions}
          onClose={() => setViewing(null)}
          onEdit={(c) => { setViewing(null); setEditing(c); }}
          onAdjustPoints={handleAdjustPoints}
        />
      )}

      {deleteConfirm && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-red-800 rounded-2xl p-6 w-full max-w-sm text-center shadow-2xl">
            <div className="text-white font-bold mb-1">Delete Customer?</div>
            <div className="text-gray-400 text-sm mb-4">"{deleteConfirm.first_name} {deleteConfirm.last_name}" will be removed.</div>
            <div className="flex gap-2">
              <button onClick={() => setDeleteConfirm(null)} className="flex-1 bg-gray-800 border border-gray-700 text-gray-300 py-2 rounded-xl text-sm transition hover:bg-gray-700">Cancel</button>
              <button onClick={() => handleDelete(deleteConfirm)} className="flex-1 bg-red-700 hover:bg-red-600 text-white font-bold py-2 rounded-xl text-sm transition">Delete</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

src/components/pos/GiftCardPanel.jsx:
import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { Gift, Plus, RefreshCw, Ban, Search } from "lucide-react";

const STATUS_COLORS = { active: "text-green-400", depleted: "text-red-400", voided: "text-gray-500" };

export default function GiftCardPanel() {
  const [cards, setCards] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [modal, setModal] = useState(null);
  const [form, setForm] = useState({ code: "", balance: "", notes: "" });
  const [reloadAmount, setReloadAmount] = useState("");
  const [saving, setSaving] = useState(false);

  const load = () => {
    setLoading(true);
    base44.entities.GiftCard.list("-created_date", 200).then(c => { setCards(c); setLoading(false); });
  };

  useEffect(() => { load(); }, []);

  const filtered = cards.filter(c => !search || c.code?.toLowerCase().includes(search.toLowerCase()));

  const issueCard = async () => {
    setSaving(true);
    const bal = parseFloat(form.balance) || 0;
    await base44.entities.GiftCard.create({
      code: form.code.toUpperCase(),
      balance: bal,
      original_balance: bal,
      status: "active",
      notes: form.notes
    });
    setSaving(false);
    setModal(null);
    setForm({ code: "", balance: "", notes: "" });
    load();
  };

  const reloadCard = async (card) => {
    setSaving(true);
    const amt = parseFloat(reloadAmount) || 0;
    await base44.entities.GiftCard.update(card.id, {
      balance: (card.balance || 0) + amt,
      status: "active"
    });
    setSaving(false);
    setModal(null);
    setReloadAmount("");
    load();
  };

  const voidCard = async (card) => {
    await base44.entities.GiftCard.update(card.id, { status: "voided", balance: 0 });
    load();
  };

  if (loading) return <div className="text-green-400 font-mono animate-pulse p-6">Loading gift cards...</div>;

  const totalValue = cards.filter(c => c.status === "active").reduce((s, c) => s + (c.balance || 0), 0);

  return (
    <div className="h-full flex flex-col">
      <div className="p-4 border-b border-gray-800 flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-[180px]">
          <Search className="absolute left-3 top-2.5 w-3.5 h-3.5 text-gray-500" />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by code…"
            className="w-full bg-gray-800 border border-gray-700 rounded-lg pl-8 pr-3 py-2 text-white text-xs font-mono focus:outline-none focus:border-green-600" />
        </div>
        <div className="text-xs font-mono text-gray-500">
          Active liability: <span className="text-green-400 font-bold">${totalValue.toFixed(2)}</span>
        </div>
        <button onClick={() => setModal("issue")}
          className="flex items-center gap-1.5 bg-green-700 hover:bg-green-600 text-white text-xs font-mono px-3 py-2 rounded-lg transition">
          <Plus className="w-3.5 h-3.5" /> Issue Gift Card
        </button>
      </div>

      <div className="flex-1 overflow-y-auto">
        <table className="w-full text-xs font-mono">
          <thead className="sticky top-0 bg-gray-900 border-b border-gray-800">
            <tr>
              {["Code", "Balance", "Original", "Status", "Issued", "Notes", "Actions"].map(h => (
                <th key={h} className="text-left text-gray-500 px-4 py-2">{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map(card => (
              <tr key={card.id} className="border-b border-gray-800/60 hover:bg-gray-800/30">
                <td className="px-4 py-2.5 text-white font-bold tracking-widest">{card.code}</td>
                <td className="px-4 py-2.5 text-green-400 font-bold">${(card.balance || 0).toFixed(2)}</td>
                <td className="px-4 py-2.5 text-gray-500">${(card.original_balance || 0).toFixed(2)}</td>
                <td className={`px-4 py-2.5 capitalize ${STATUS_COLORS[card.status] || "text-gray-400"}`}>{card.status}</td>
                <td className="px-4 py-2.5 text-gray-500">
                  {card.created_date ? new Date(card.created_date).toLocaleDateString() : "—"}
                </td>
                <td className="px-4 py-2.5 text-gray-500">{card.notes || "—"}</td>
                <td className="px-4 py-2.5">
                  <div className="flex gap-2">
                    {card.status === "active" && (
                      <button onClick={() => { setModal({ card, type: "reload" }); setReloadAmount(""); }}
                        className="text-gray-500 hover:text-blue-400 transition" title="Reload">
                        <RefreshCw className="w-3.5 h-3.5" />
                      </button>
                    )}
                    {card.status !== "voided" && (
                      <button onClick={() => voidCard(card)} className="text-gray-500 hover:text-red-400 transition" title="Void">
                        <Ban className="w-3.5 h-3.5" />
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr><td colSpan={7} className="text-gray-600 text-center py-12 font-mono">No gift cards found</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {modal === "issue" && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 w-full max-w-sm">
            <div className="text-white font-bold mb-4 flex items-center gap-2"><Gift className="w-4 h-4 text-pink-400" /> Issue Gift Card</div>
            <div className="space-y-3">
              <div>
                <label className="text-gray-500 text-xs font-mono block mb-1">Card Code</label>
                <input value={form.code} onChange={e => setForm(p => ({ ...p, code: e.target.value }))} placeholder="GC-2024-XXXX"
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
              </div>
              <div>
                <label className="text-gray-500 text-xs font-mono block mb-1">Initial Balance ($)</label>
                <input type="number" value={form.balance} onChange={e => setForm(p => ({ ...p, balance: e.target.value }))} placeholder="25.00"
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
              </div>
              <div>
                <label className="text-gray-500 text-xs font-mono block mb-1">Notes (optional)</label>
                <input value={form.notes} onChange={e => setForm(p => ({ ...p, notes: e.target.value }))} placeholder="Customer name, occasion…"
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
              </div>
            </div>
            <div className="flex gap-2 mt-4">
              <button onClick={() => setModal(null)} className="flex-1 bg-gray-800 hover:bg-gray-700 border border-gray-700 text-gray-300 py-2 rounded-xl text-sm transition">Cancel</button>
              <button onClick={issueCard} disabled={saving || !form.code || !form.balance}
                className="flex-1 bg-green-700 hover:bg-green-600 disabled:opacity-40 text-white font-bold py-2 rounded-xl text-sm transition">
                {saving ? "Issuing…" : "Issue Card"}
              </button>
            </div>
          </div>
        </div>
      )}

      {modal?.type === "reload" && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-gray-700 rounded-2xl p-6 w-full max-w-sm">
            <div className="text-white font-bold mb-1">Reload Gift Card</div>
            <div className="text-green-400 font-mono text-sm mb-4">{modal.card.code} — Balance: ${(modal.card.balance || 0).toFixed(2)}</div>
            <div>
              <label className="text-gray-500 text-xs font-mono block mb-1">Add Amount ($)</label>
              <input type="number" value={reloadAmount} onChange={e => setReloadAmount(e.target.value)} placeholder="0.00" autoFocus
                className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-sm font-mono focus:outline-none focus:border-green-500" />
            </div>
            <div className="flex gap-2 mt-4">
              <button onClick={() => setModal(null)} className="flex-1 bg-gray-800 hover:bg-gray-700 border border-gray-700 text-gray-300 py-2 rounded-xl text-sm transition">Cancel</button>
              <button onClick={() => reloadCard(modal.card)} disabled={saving || !reloadAmount}
                className="flex-1 bg-blue-700 hover:bg-blue-600 disabled:opacity-40 text-white font-bold py-2 rounded-xl text-sm transition">
                {saving ? "Reloading…" : "Reload Card"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

src/components/pos/InventoryPanel.jsx:
import React, { useState, useEffect } from "react";
import { base44 } from "@/api/base44Client";
import { Search, Plus, Pencil, Trash2, X, AlertTriangle, CheckSquare, Printer } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import ProductFormModal from "./ProductFormModal";
import ProductLabelPrint from "./ProductLabelPrint";

const CATEGORIES = ["Food", "Beverage", "Electronics", "Clothing", "Health", "Household", "Other"];

export default function InventoryPanel() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState(null); // null | "new" | product object
  const [deleteConfirm, setDeleteConfirm] = useState(null);
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [selected, setSelected] = useState(new Set());
  const [bulkDeleteConfirm, setBulkDeleteConfirm] = useState(false);
  const [printProducts, setPrintProducts] = useState(null); // null | product[]

  useEffect(() => {
    load();
  }, []);

  const load = () => {
    setLoading(true);
    base44.entities.Product.list("name", 500).then(p => {
      setProducts(p);
      setLoading(false);
    });
  };

  const filtered = products.filter(p => {
    const matchSearch = !search || p.name?.toLowerCase().includes(search.toLowerCase()) || p.barcode?.includes(search);
    const matchCat = categoryFilter === "all" || p.category === categoryFilter;
    return matchSearch && matchCat;
  });

  const openNew = () => setEditing("new");
  const openEdit = (p) => setEditing(p);
  const closeEdit = () => setEditing(null);

  const handleDelete = async (product) => {
    await base44.entities.Product.delete(product.id);
    setDeleteConfirm(null);
    load();
  };

  const toggleSelect = (id) => {
    setSelected(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const toggleSelectAll = () => {
    if (selected.size === filtered.length) {
      setSelected(new Set());
    } else {
      setSelected(new Set(filtered.map(p => p.id)));
    }
  };

  const handleBulkDelete = async () => {
    await Promise.all([...selected].map(id => base44.entities.Product.delete(id)));
    setSelected(new Set());
    setBulkDeleteConfirm(false);
    load();
  };



  const stockColor = (stock) => {
    if (stock <= 0) return "text-red-400";
    if (stock <= 5) return "text-amber-400";
    return "text-green-400";
  };

  if (loading) return <div className="text-green-400 font-mono animate-pulse p-6">Loading inventory...</div>;

  return (
    <div className="h-full flex flex-col">
      {/* Toolbar */}
      <div className="p-4 border-b border-gray-800 flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-[180px]">
          <Search className="absolute left-3 top-2.5 w-3.5 h-3.5 text-gray-500" />
          <input value={search} onChange={e => setSearch(e.target.value)}
            placeholder="Search name or barcode…"
            className="w-full bg-gray-800 border border-gray-700 rounded-lg pl-8 pr-3 py-2 text-white text-xs font-mono focus:outline-none focus:border-green-600 transition" />
        </div>
        <select value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)}
          className="bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-gray-300 text-xs font-mono focus:outline-none focus:border-green-600 transition">
          <option value="all">All Categories</option>
          {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        <button onClick={openNew}
          className="flex items-center gap-1.5 bg-green-700 hover:bg-green-600 text-white text-xs font-mono px-3 py-2 rounded-lg transition">
          <Plus className="w-3.5 h-3.5" /> Add Product
        </button>
        <div className="text-gray-600 text-xs font-mono">{filtered.length} items</div>
      </div>

      {/* Table */}
      <div className="flex-1 overflow-y-auto">
        {filtered.length === 0 ? (
          <div className="text-gray-600 font-mono text-sm text-center py-16">No products found</div>
        ) : (
          <table className="w-full text-xs font-mono">
            <thead className="sticky top-0 bg-gray-900 border-b border-gray-800">
              <tr>
                <th className="px-4 py-2 w-8">
                  <input type="checkbox"
                    checked={filtered.length > 0 && selected.size === filtered.length}
                    ref={el => { if (el) el.indeterminate = selected.size > 0 && selected.size < filtered.length; }}
                    onChange={toggleSelectAll}
                    className="w-3.5 h-3.5 cursor-pointer accent-green-500" />
                </th>
                {["Name", "Barcode", "Category", "Price", "Stock", "Age 18+", "Actions"].map(h => (
                  <th key={h} className="text-left text-gray-500 px-4 py-2 font-medium">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filtered.map(p => (
                <tr key={p.id} className={`border-b border-gray-800/60 hover:bg-gray-800/30 transition ${selected.has(p.id) ? "bg-green-900/10" : ""}`}>
                  <td className="px-4 py-2.5">
                    <input type="checkbox" checked={selected.has(p.id)} onChange={() => toggleSelect(p.id)}
                      className="w-3.5 h-3.5 cursor-pointer accent-green-500" />
                  </td>
                  <td className="px-4 py-2.5 text-white font-semibold">{p.name}</td>
                  <td className="px-4 py-2.5 text-gray-500">{p.barcode || "—"}</td>
                  <td className="px-4 py-2.5 text-gray-400">{p.category || "—"}</td>
                  <td className="px-4 py-2.5 text-green-400 font-bold">${(p.price || 0).toFixed(2)}</td>
                  <td className={`px-4 py-2.5 font-bold ${stockColor(p.stock || 0)}`}>{p.stock ?? "—"}</td>
                  <td className="px-4 py-2.5">
                    {p.age_restricted ? <span className="text-amber-400 font-bold">YES</span> : <span className="text-gray-600">No</span>}
                  </td>
                  <td className="px-4 py-2.5">
                    <div className="flex gap-2">
                      <button onClick={() => openEdit(p)} className="text-gray-500 hover:text-blue-400 transition" title="Edit"><Pencil className="w-3.5 h-3.5" /></button>
                      <button onClick={() => setPrintProducts([p])} className="text-gray-500 hover:text-green-400 transition" title="Print Label"><Printer className="w-3.5 h-3.5" /></button>
                      <button onClick={() => setDeleteConfirm(p)} className="text-gray-500 hover:text-red-400 transition" title="Delete"><Trash2 className="w-3.5 h-3.5" /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {editing !== null && (
        <ProductFormModal editing={editing} onClose={closeEdit} onSaved={() => { closeEdit(); load(); }} />
      )}

      {printProducts && (
        <ProductLabelPrint products={printProducts} onClose={() => setPrintProducts(null)} />
      )}

      {/* Floating Bulk Toolbar */}
      <AnimatePresence>
        {selected.size > 0 && (
          <motion.div
            initial={{ y: 80, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: 80, opacity: 0 }}
            className="fixed bottom-6 left-1/2 -translate-x-1/2 z-40 flex items-center gap-3 bg-gray-800 border border-gray-600 rounded-2xl px-5 py-3 shadow-2xl"
          >
            <CheckSquare className="w-4 h-4 text-green-400" />
            <span className="text-white text-xs font-mono font-bold">{selected.size} selected</span>
            <div className="w-px h-5 bg-gray-600" />
            <button
              onClick={() => setPrintProducts(products.filter(p => selected.has(p.id)))}
              className="flex items-center gap-1.5 bg-green-900/50 hover:bg-green-800 border border-green-700 text-green-300 text-xs font-mono px-3 py-1.5 rounded-lg transition">
              <Printer className="w-3.5 h-3.5" /> Print Labels
            </button>
            <button
              onClick={() => setBulkDeleteConfirm(true)}
              className="flex items-center gap-1.5 bg-red-900/50 hover:bg-red-800 border border-red-700 text-red-300 text-xs font-mono px-3 py-1.5 rounded-lg transition">
              <Trash2 className="w-3.5 h-3.5" /> Delete Selected
            </button>
            <button onClick={() => setSelected(new Set())} className="text-gray-500 hover:text-gray-300 transition">
              <X className="w-4 h-4" />
            </button>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Bulk Delete Confirm */}
      {bulkDeleteConfirm && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-red-800 rounded-2xl p-6 w-full max-w-sm text-center shadow-2xl">
            <AlertTriangle className="w-10 h-10 text-red-400 mx-auto mb-3" />
            <div className="text-white font-bold mb-1">Delete {selected.size} Products?</div>
            <div className="text-gray-400 text-sm mb-4">This action cannot be undone.</div>
            <div className="flex gap-2">
              <button onClick={() => setBulkDeleteConfirm(false)} className="flex-1 bg-gray-800 hover:bg-gray-700 border border-gray-700 text-gray-300 py-2 rounded-xl text-sm transition">Cancel</button>
              <button onClick={handleBulkDelete} className="flex-1 bg-red-700 hover:bg-red-600 text-white font-bold py-2 rounded-xl text-sm transition">Delete All</button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirm */}
      {deleteConfirm && (
        <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-red-800 rounded-2xl p-6 w-full max-w-sm text-center shadow-2xl">
            <AlertTriangle className="w-10 h-10 text-red-400 mx-auto mb-3" />
            <div className="text-white font-bold mb-1">Delete Product?</div>
            <div className="text-gray-400 text-sm mb-4">"{deleteConfirm.name}" will be permanently removed.</div>
            <div className="flex gap-2">
              <button onClick={() => setDeleteConfirm(null)} className="flex-1 bg-gray-800 hover:bg-gray-700 border border-gray-700 text-gray-300 py-2 rounded-xl text-sm transition">Cancel</button>
              <button onClick={() => handleDelete(deleteConfirm)} className="flex-1 bg-red-700 hover:bg-red-600 text-white font-bold py-2 rounded-xl text-sm transition">Delete</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

src/components/pos/LaneLockScreen.jsx:
import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Lock, AlertCircle, ShieldCheck } from "lucide-react";
import { usePOS } from "./POSContext";
import { base44 } from "@/api/base44Client";

export default function LaneLockScreen() {
  const { loginStaff, failedAttempts, lockedOut, lockoutEnd, CONFIG, setLockedOut, setFailedAttempts, setCurrentStaff, setPhase, logEvent } = usePOS();
  const [pin, setPin] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [time, setTime] = useState(new Date());
  const [countdown, setCountdown] = useState(0);
  const [adminOverride, setAdminOverride] = useState(false);
  const [adminPin, setAdminPin] = useState("");
  const [adminError, setAdminError] = useState("");

  useEffect(() => {
    const t = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    if (lockedOut && lockoutEnd) {
      const t = setInterval(() => {
        const rem = Math.ceil((lockoutEnd - Date.now()) / 1000);
        setCountdown(rem > 0 ? rem : 0);
      }, 500);
      return () => clearInterval(t);
    }
  }, [lockedOut, lockoutEnd]);

  const handleKey = async (k) => {
    if (lockedOut) return;
    if (k === "DEL") { setPin(p => p.slice(0, -1)); return; }
    if (k === "ENTER") {
      if (pin.length < 4) { setError("PIN must be at least 4 digits"); return; }
      setLoading(true);
      setError("");
      const res = await loginStaff(pin);
      setLoading(false);
      if (!res.success) { setError(res.error); setPin(""); }
      return;
    }
    if (pin.length < 8) setPin(p => p + k);
  };

  const handleAdminKey = async (k) => {
    if (k === "DEL") { setAdminPin(p => p.slice(0, -1)); return; }
    if (k === "ENTER") {
      if (adminPin.length < 4) { setAdminError("PIN must be at least 4 digits"); return; }
      const staffList = await base44.entities.Staff.list();
      const admin = staffList.find(s => s.pin === adminPin && s.active && (s.role === "administrator" || s.role === "manager"));
      if (admin) {
        setLockedOut(false);
        setFailedAttempts(0);
        setAdminOverride(false);
        setAdminPin("");
        setAdminError("");
        // loginStaff won't work since lockedOut is being reset; just do it directly
        setCurrentStaff(admin);
        logEvent("admin_override_unlock", `Terminal unlocked by admin: ${admin.name}`, { staff_id: admin.staff_id });
        setPhase("shift_start");
      } else {
        setAdminError("Invalid admin/manager PIN");
        setAdminPin("");
      }
      return;
    }
    if (adminPin.length < 8) setAdminPin(p => p + k);
  };

  const keys = ["1","2","3","4","5","6","7","8","9","DEL","0","ENTER"];

  return (
    <div className="min-h-screen bg-gray-950 flex flex-col items-center justify-center select-none">
      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        className="w-full max-w-sm px-6"
      >
        {/* Header */}
        <div className="text-center mb-8">
          <motion.div
            animate={{ scale: [1, 1.05, 1] }}
            transition={{ repeat: Infinity, duration: 2 }}
            className="inline-flex items-center justify-center w-16 h-16 bg-gray-800 rounded-full mb-4 border border-gray-700"
          >
            <Lock className="w-8 h-8 text-amber-400" />
          </motion.div>
          <div className="text-white text-xl font-bold tracking-widest font-mono">POS TERMINAL LOCKED</div>
          <div className="text-gray-500 text-sm mt-1 font-mono">
            Store: {CONFIG.store_id} &nbsp;|&nbsp; Lane: {CONFIG.terminal_id}
          </div>
          <div className="text-gray-400 font-mono text-2xl font-bold mt-3">
            {time.toLocaleTimeString()}
          </div>
          <div className="text-gray-600 font-mono text-xs mt-0.5">{time.toLocaleDateString("en-US", { day: "numeric", month: "long", year: "numeric" })}</div>
        </div>

        {lockedOut ? (
          <div className="text-center">
            <div className="bg-red-900/40 border border-red-700 rounded-xl p-4 mb-4">
              <AlertCircle className="w-6 h-6 text-red-400 mx-auto mb-2" />
              <div className="text-red-400 font-bold text-sm">TERMINAL LOCKED</div>
              <div className="text-red-300 text-xs mt-1">Too many failed attempts</div>
              <div className="text-white text-2xl font-mono font-bold mt-2">{countdown}s</div>
            </div>

            {!adminOverride ? (
              <button
                onClick={() => { setAdminOverride(true); setAdminError(""); setAdminPin(""); }}
                className="flex items-center gap-2 mx-auto text-amber-400 hover:text-amber-300 text-xs font-mono border border-amber-800 hover:border-amber-600 rounded-lg px-4 py-2 transition">
                <ShieldCheck className="w-4 h-4" />
                Admin Override
              </button>
            ) : (
              <div className="mt-2">
                <div className="text-amber-400 text-xs font-mono mb-3 flex items-center justify-center gap-1">
                  <ShieldCheck className="w-3.5 h-3.5" /> Enter Admin / Manager PIN
                </div>
                <div className="flex justify-center gap-2 mb-3">
                  {Array.from({ length: Math.max(4, adminPin.length) }).map((_, i) => (
                    <div key={i} className={`w-9 h-9 rounded-lg border flex items-center justify-center ${
                      i < adminPin.length ? "border-amber-500 bg-amber-900/30" : "border-gray-700 bg-gray-900"
                    }`}>
                      {i < adminPin.length && <div className="w-2.5 h-2.5 rounded-full bg-amber-400" />}
                    </div>
                  ))}
                </div>
                {adminError && <div className="text-red-400 text-xs font-mono mb-2">{adminError}</div>}
                <div className="grid grid-cols-3 gap-2 mb-3">
                  {keys.map(k => (
                    <button key={k} onClick={() => handleAdminKey(k)}
                      className={`h-11 rounded-xl font-mono font-bold text-sm transition-all active:scale-95 ${
                        k === "ENTER" ? "bg-amber-700 hover:bg-amber-600 text-white border border-amber-500"
                        : k === "DEL" ? "bg-gray-800 hover:bg-gray-700 text-gray-300 border border-gray-700"
                        : "bg-gray-800 hover:bg-gray-700 text-white border border-gray-700"
                      }`}>{k}</button>
                  ))}
                </div>
                <button onClick={() => { setAdminOverride(false); setAdminPin(""); setAdminError(""); }}
                  className="text-gray-600 hover:text-gray-400 text-xs font-mono transition">Cancel</button>
              </div>
            )}
          </div>
        ) : (
          <>
            {/* PIN display */}
            <div className="flex justify-center gap-3 mb-4">
              {Array.from({ length: Math.max(4, pin.length) }).map((_, i) => (
                <div key={i} className={`w-10 h-10 rounded-lg border flex items-center justify-center ${
                  i < pin.length ? "border-green-500 bg-green-900/30" : "border-gray-700 bg-gray-900"
                }`}>
                  {i < pin.length && <div className="w-3 h-3 rounded-full bg-green-400" />}
                </div>
              ))}
            </div>

            {error && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="text-red-400 text-xs text-center mb-3 font-mono">
                {error} {failedAttempts > 0 && `(${failedAttempts}/5 attempts)`}
              </motion.div>
            )}

            {/* Numpad */}
            <div className="grid grid-cols-3 gap-2 mb-4">
              {keys.map(k => (
                <button
                  key={k}
                  onClick={() => handleKey(k)}
                  disabled={loading}
                  className={`h-12 rounded-xl font-mono font-bold text-sm transition-all active:scale-95 ${
                    k === "ENTER"
                      ? "bg-green-700 hover:bg-green-600 text-white border border-green-500"
                      : k === "DEL"
                      ? "bg-gray-800 hover:bg-gray-700 text-gray-300 border border-gray-700"
                      : "bg-gray-800 hover:bg-gray-700 text-white border border-gray-700"
                  }`}
                >
                  {k}
                </button>
              ))}
            </div>

            <div className="text-center text-gray-600 text-xs font-mono">
              Waiting for staff login
            </div>

            <div className="mt-4 bg-gray-900 border border-gray-800 rounded-xl p-3">
              <div className="text-gray-600 text-xs font-mono mb-2">DEV — DEMO PINS</div>
              <div className="grid grid-cols-2 gap-1 text-xs font-mono">
                <div className="text-gray-500">Admin: <span className="text-green-400">0000</span></div>
                <div className="text-gray-500">Manager: <span className="text-blue-400">1234</span></div>
                <div className="text-gray-500">Supervisor: <span className="text-amber-400">5678</span></div>
                <div className="text-gray-500">Cashier: <span className="text-gray-300">9012</span></div>
              </div>
            </div>
          </>
        )}
      </motion.div>
    </div>
  );
}

